INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 25 anos, submetido a fixação intramedular de fratura de fêmur há 24 horas, desenvolve subitamente dispneia, taquicardia e confusão mental. Ao exame físico, observa-se a presença de petéquias em região axilar e conjuntival. Qual a principal suspeita clínica para esta complicação traumato-ortopédica?", "options": {"a": "Tromboembolismo Pulmonar (TEP).", "b": "Síndrome de Embolia Gordurosa.", "c": "Sepse por infecção de sítio cirúrgico precoce.", "d": "Contusão pulmonar não diagnosticada.", "e": "Choque hipovolêmico tardio."}, "answer": "b", "rationale": "A tríade clássica de insuficiência respiratória, alterações neurológicas e petéquias em um paciente com fratura de ossos longos após 24-72h é altamente sugestiva de embolia gordurosa.", "option_rationales": {"a": "Incorreta. TEP não costuma causar petéquias.", "b": "Correta. Diagnóstico clínico baseado na apresentação e histórico.", "c": "Incorreta. Muito precoce e as petéquias não são típicas de sepse bacteriana comum inicial.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Ortopedia", "Pós-operatório", "Embolia Gordurosa", "Complicações"]}', 101, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma neurocirurgia para ressecção de tumor de hipófise, o paciente apresenta poliúria súbita (débito urinário > 500 ml/h) e sede intensa. A densidade urinária é baixa (1.002) e o sódio sérico está elevado (155 mEq/L). Qual o diagnóstico e o tratamento de escolha?", "options": {"a": "Diabetes Insipidus Central; administração de desmopressina (DDAVP).", "b": "SIADH; restrição hídrica.", "c": "Sindrome cerebral perdedora de sal; reposição de sal.", "d": "Hiperglicemia severa; insulina.", "e": "Insuficiência renal aguda; diálise."}, "answer": "a", "rationale": "A manipulação da região hipofisária pode causar deficiência transisória ou permanente de ADH, levando ao Diabetes Insipidus central, caracterizado por urina diluída e hipernatremia plasmática.", "option_rationales": {"a": "Correta. Quadro clínico e tratamento de substituição hormonal.", "b": "Incorreta. SIADH causaria hiponatremia por diluição.", "c": "Incorreta. Causaria hiponatremia por perda de sódio na urina.", "d": "Incorreta. Densidade urinária seria alta pela glicosúria.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "Diabetes Insipidus", "Complicações Endócrinas"]}', 102, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''febre'' nas primeiras 4 a 6 horas após o término de uma cirurgia realizada sob anestesia geral, se o paciente estiver na sala de recuperação e apresentar tremores generalizados?", "options": {"a": "Infecção por clostrídios.", "b": "Hipertermia Maligna.", "c": "Hipotermia perioperatória com tremores compensatórios (shivering) e resposta inflamatória inicial.", "d": "Reação hemolítica aguda.", "e": "Pneumonia nosocomial."}, "answer": "c", "rationale": "A hipotermia é muito comum no transoperatório e o organismo reage com tremores (shivering) para produzir calor, o que pode mimetizar um estado febril inicial ou levar a uma febre reacional ao estresse cirúrgico.", "option_rationales": {"a": "Incorreta. Precoce demais.", "b": "Incorreta. Hipertermia maligna ocorre durante a anestesia e causa rigidez, não apenas tremores de frio, e temperaturas muito altas.", "c": "Correta. Causa muito comum de alteração térmica precoce.", "d": "Incorreta. Reação hemolítica causaria hipotensão e dor lombar severa.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Hipotermia", "Tremores"]}', 103, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia cardíaca eletiva apresenta no pós-operatório imediato queda do débito urinário, taquidispneia, abafamento de bulhas cardíacas e turgência jugular que aumenta à inspiração (Sinal de Kussmaul). O dreno de tórax, que vinha drenando 200 ml/h, parou de drenar subitamente. Qual a principal suspeita diagnóstica?", "options": {"a": "Embolia pulmonar.", "b": "Infarto do VD.", "c": "Tamponado cardíaco agudo por obstrução do dreno.", "d": "Pneumotórax hipertensivo.", "e": "Crise hipertensiva."}, "answer": "c", "rationale": "O tamponamento é uma complicação crítica da cirurgia cardíaca. A tríade de Beck (hipotensão, bulhas abafadas e turgência jugular) e o sinal de Kussmaul apontam para restrição ao enchimento cardíaco.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. A parada brusca da drenagem sugere obstrução do tubo por coágulos, acumulando sangue no pericárdio ou mediastino.", "d": "Incorreta. Ausculta pulmonar estaria alterada e a traqueia desviada.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Tamponamento", "Emergência"]}', 104, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A classificação da ferida operatória em ''Limpa-Contaminada'' aplica-se a qual dos cenários abaixo de acordo com as diretrizes de ISC?", "options": {"a": "Herniorrafia inguinal sem tela.", "b": "Colecistectomia eletiva com abertura programada e controlada da via biliar.", "c": "Cirurgia de trauma abdominal com perfuração de cólon há 6 horas.", "d": "Drenagem de abscesso perianal.", "e": "Tireoidectomia."}, "answer": "b", "rationale": "Feridas limpa-contaminadas são aquelas em que os tratos respiratório, alimentar, genital ou urinário são penetrados sob condições controladas e sem contaminação incomum.", "option_rationales": {"a": "Incorreta. Essa é Limpa.", "b": "Correta. Exemplo clássico de penetração biliar controlada.", "c": "Incorreta. Essa é Contaminada ou Suja (dependendo do tempo e conteúdo fecal livre).", "d": "Incorreta. Essa é Suja/Infectada.", "e": "Incorreta. Essa é Limpa."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Classificação de Ferida"]}', 105, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta imediata diante de uma reação transfusional caracterizada por febre, calafrios e tremores sem sinais de hemólise ou hipotensão (Reação Febril Não Hemolítica)?", "options": {"a": "Manter a transfusão e dar dipirona.", "b": "Interromper a transfusão imediatamente, manter acesso com solução salina e administrar antitérmicos.", "c": "Administrar adrenalina intramuscular.", "d": "Solicitar tomografia de tórax.", "e": "Trocar o dreno do paciente."}, "answer": "b", "rationale": "Sempre que houver reação durante a transfusão, o primeiro passo é parar a infusão para investigar se a reação é simples (febril) ou grave (hemolítica/septica).", "option_rationales": {"a": "Incorreta. Perigoso antes de descartar hemólise.", "b": "Correta. Protocolo de segurança transfusional.", "c": "Incorreta. Indicado apenas em anafilaxia.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Hematologia", "Pós-operatório", "Transfusão", "Segurança"]}', 106, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente asplênico (pós-esplenectomia) que apresenta febre deve ser tratado de forma agressiva. Qual a conduta empírica inicial recomendada caso ele apresente febre em domicílio e não consiga chegar rapidamente ao hospital?", "options": {"a": "Aguardar 24 horas para ver se a febre cede.", "b": "Uso de antibiótico de reserva domiciliar (como Amoxicilina/Clavulanato ou Levofloxacino) orientado previamente pelo cirurgião.", "c": "Tomar apenas antitérmicos e hidratação oral.", "d": "Realizar compressas frias.", "e": "Apenas observação."}, "answer": "b", "rationale": "Devido ao risco de progressão fulminante da sepse no asplênico, recomenda-se que esses pacientes tenham antibióticos de emergência em casa para início imediato ao primeiro sinal de febre.", "option_rationales": {"a": "Incorreta. Pode ser fatal em poucas horas.", "b": "Correta. Estratégia de segurança recomendada em diretrizes de asplenia.", "c": "Incorreta. Máscara o sintoma sem tratar a causa perigosa.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Esplenectomia", "OPSI", "Prevenção"]}', 107, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma gastrectomia total, o dreno abdominal mostra saída de conteúdo bilioso (verde-amarelado) no 4º DPO. O cirurgião suspeita de deiscência da anastomose esofagojejunal ou do coto duodenal. Qual exame de imagem é mais sensível para identificar extravasamento de contraste nestas anastomoses altas?", "options": {"a": "Radiografia simples de abdome em pé.", "b": "Seriografia de esôfago-estômago-duodeno (SEED) com contraste hidrossolúvel.", "c": "Tomografia com contraste venoso apenas.", "d": "Ultrassonografia transvaginal.", "e": "Cintilografia óssea."}, "answer": "b", "rationale": "O contraste hidrossolúvel (Gastrografin) é seguro se houver perfuração (não causa peritonite química como o bário) e permite visualizar o ponto exato da fístula sob radioscopia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Exame dinâmico para fístulas altas.", "c": "Incorreta. O contraste deve ser oral/entérico para ver o vazamento da anastomose.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Radiologia"]}', 108, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia colorretal desenvolve íleo adinâmico prolongado. Os níveis de potássio estão em 3,0 mEq/L e o médico prescreve reposição de potássio. No entanto, após 24 horas de reposição vigorosa, o potássio continua em 3,1 mEq/L. Qual deficiência de outro eletrólito pode estar impedindo a correção da calemia?", "options": {"a": "Hiponatremia.", "b": "Hipomagnesemia.", "c": "Hipercalcemia.", "d": "Hiperfosfatemia.", "e": "Hipotireoidismo."}, "answer": "b", "rationale": "O magnésio é um cofator necessário para o funcionamento da bomba Na+/K+ ATPase e para o canal ROMK no rim. Se o magnésio estiver baixo, o rim continua excretando potássio mesmo com a reposição.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Hipocalemia refratária é quase sempre associada a hipomagnesemia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Gastroenterologia", "Pós-operatório", "Eletrólitos", "Hipomagnesemia"]}', 109, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 2º DPO de uma cirurgia de grande porte, o paciente apresenta diurese de 20 ml/h, taquicardia e extremidades frias. Qual a primeira medida terapêutica indicada após excluir sinais de congestão pulmonar?", "options": {"a": "Administrar 40 mg de Furosemida venosa.", "b": "Oferecer 500 ml a 1.000 ml de cristaloide em bólus (desafio volêmico).", "c": "Iniciar Noradrenalina.", "d": "Solicitar ecocardiograma.", "e": "Reiniciar dieta oral."}, "answer": "b", "rationale": "A oligúria precoce no pós-operatório é mais frequentemente hipovolêmica (pré-renal). O desafio volêmico ajuda a distinguir falha renal renal estabelecida de déficit de volume.", "option_rationales": {"a": "Incorreta. Diuréticos no paciente hipovolêmico pioram a lesão renal.", "b": "Correta. Conduta de ressuscitação inicial padrão.", "c": "Incorreta. Vasopressores só após reposição volêmica adequada estar falhando.", "d": "Incorreta. Útil mais tarde, mas a prioridade inicial é volume.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "Oligúria", "Hidratação"]}', 110, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''hemoperitônio'' tardio (após 5-7 dias da cirurgia), manifestando-se por dor abdominal súbita e choque hemorrágico inexplicado após uma gastrectomia distal por câncer?", "options": {"a": "Ruptura de pseudocisto pancreático.", "b": "Sangramento do leito cirúrgico estabilizado.", "c": "Deiscência da anastomose gastro-jejunal.", "d": "Lesão iatrogênica da artéria esplênica não vista.", "e": "Ressangramento de vasos da pequena ou grande curvatura por desprendimento tardio de grampos ou ligaduras (Raramente) ou pseudoaneurisma por fístula adjacente."}, "answer": "e", "rationale": "Embora o sangramento precoce seja frequente por falha técnica, o sangramento tardio associado a fístulas pancreáticas ou entéricas pode ser decorrente da erosão de vasos por enzimas digestivas (pseudoaneurismas).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta. Deiscência dá peritonite, não hemoperitônio maciço isolado.", "d": "Incorreta. Estaria presente precocemente.", "e": "Correta. Fisiopatologia do sangramento sentinela/tardio."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Hemorragia Tardia", "Pseudoaneurisma"]}', 111, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 80 anos, no 3º DPO de uma colectomia, queixa-se de náuseas. O médico prescreve metoclopramida (Plasil). Horas depois, o paciente apresenta agitação motora extrema, incapacidade de ficar parado e movimentos involuntários da face. Qual o nome deste efeito colateral e o antídoto?", "options": {"a": "Reação extra-piramidal; Biperideno ou Difenidramina.", "b": "AVC isquêmico; AAS.", "c": "Hipotensão postural; Volume.", "d": "Sindrome do pânico; Ansioítico.", "e": "Intoxicação por Opioides; Naloxona."}, "answer": "a", "rationale": "A metoclopramida pode causar reações distônicas agudas e acatisia por seu efeito de bloqueio dopaminérgico central. O tratamento é feito com agentes anticolinérgicos.", "option_rationales": {"a": "Correta. Quadro clínico de acatisia iatrogênica e tratamento correto.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Farmacodinâmica", "Idoso"]}', 112, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A infecção da ferida operatória classificada como ''ISC Órgão/Espaço'' após uma apendicectomia é exemplificada por:", "options": {"a": "Vermelhidão na pele da incisão.", "b": "Saída de pus apenas do subcutâneo.", "c": "Abscesso intra-abdominal entre alças de delgado.", "d": "Hérnia após cicatrização.", "e": "Hematoma da ferida."}, "answer": "c", "rationale": "ISC Órgão/Espaço ocorre em qualquer parte da anatomia aberta ou manipulada durante a cirurgia, exceto a incisão em si (pele, fáscia, músculo).", "option_rationales": {"a": "Incorreta. É superficial.", "b": "Incorreta. É superficial.", "c": "Correta. Abscesso intra-cavitário é o exemplo clássico.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Classificação"]}', 113, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A medida profilática mais eficaz e de baixo custo para prevenir pneumonia nosocomial em pacientes cirúrgicos estáveis de enfermaria é:", "options": {"a": "Uso de antibiótico inalatório.", "b": "Deambulação precoce e fisioterapia respiratória com exercícios de expansão.", "c": "Uso de xarope para tosse.", "d": "Jejum total por 5 dias.", "e": "Vaporização no quarto."}, "answer": "b", "rationale": "O estímulo à tosse, a caminhada precoce e a mudança de decúbito previnem o acúmulo de secreções e atelectasias, reduzindo a chance de pneumonia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Pilares da recuperação cirúrgica.", "c": "Incorreta. Antitussígenos podem ser prejudiciais se impedirem a limpeza da via aérea.", "d": "Incorreta. Desnutrição piora a imunidade pulmonar.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Pneumologia", "Pós-operatório", "Pneumonia", "Prevenção"]}', 114, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia urológica prolongada em posição de litotomia exagerada queixa-se no pós-operatório de dormência e fraqueza para realizar a flexão dorsal do pé (pé caído). Qual o nervo afetado e o local da compressão?", "options": {"a": "Nervo Femoral; ligamento inguinal.", "b": "Nervo Fibular Comum; cabeça da fíbula.", "c": "Nervo Ciático; glúteo.", "d": "Nervo Obturador; canal obturatório.", "e": "Nervo Pudendo; sínfise púbica."}, "answer": "b", "rationale": "A compressão do nervo fibular comum contra os suportes da mesa cirúrgica (perneiras) na região da cabeça da fíbula é uma neuropatia posicional clássica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Causa comum de neuropatia em cirurgia urológica/ginecológica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Posicionamento", "Nervo Fibular"]}', 115, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 45 anos, no 2º DPO de uma colecistectomia videolaparoscópica, apresenta dor intensa em ombro direito. O paciente está afebril, com abdome indolor e sinais vitais normais. Qual a explicação para esta dor e a conduta correta?", "options": {"a": "IAM apical; ECG imediato.", "b": "Coleção subfrênica; USG abdome.", "c": "Irritação do nervo frênico pelo CO2 residual (Pneumoperitônio); tranquilização e analgésicos simples.", "d": "Luxação de ombro durante posicionamento.", "e": "Derrame pleural pleural direito."}, "answer": "c", "rationale": "A dor referida no ombro após laparoscopia é causada pela irritação dos nervos frênicos pelo gás carbônico residual usado para criar o pneumoperitônio. É benigna e autolimitada.", "option_rationales": {"a": "Incorreta. Dor de ombro isolada sem outros sintomas e após laparoscopia sugere causa gástrica/diafragmática primeiro.", "b": "Incorreta. Muito precoce para abscesso pós-laparoscopia simples.", "c": "Correta. Fenômeno benigno e frequente.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Laparoscopia", "Dor Referida"]}', 116, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal vantagem da anestesia peridural torácica associada à anestesia geral em cirurgias abdominais altas e torácicas no que diz respeito ao sistema respiratório?", "options": {"a": "Aumenta a força dos músculos intercostais.", "b": "Permite melhor controle da dor, favorecendo respirações profundas e tosse eficaz, reduzindo atelectasias.", "c": "Reduz o risco de embolia gordurosa.", "d": "Impede a ocorrência de náuseas.", "e": "Acelera o tempo de esvaziamento gástrico."}, "answer": "b", "rationale": "A analgesia regional superior permite que o paciente respire melhor sem a limitação álgica, o que é fundamental para evitar complicações pulmonares restritivas.", "option_rationales": {"a": "Incorreta. Na verdade, pode causar leve fraqueza, mas o benefício analgésico supera.", "b": "Correta. Principal benefício respiratório da analgesia epidural.", "c": "Incorreta.", "d": "Incorreta. Pode até aumentar náuseas pela hipotensão.", "e": "Incorreta. Pode retardar levemente por efeito simpaticolítico."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Analgesia Epidural", "Pulmonar"]}', 117, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma esternotomia mediana por troca valvar, o dreno mediastinal apresenta saída de líquido límpido pálido com aparência de soro. Nas últimas horas, o débito aumentou para 1.500 ml. Ao medir a pressão venosa central, observa-se que está normal. O paciente está estável. Qual a explicação mais provável se este líquido for quilo?", "options": {"a": "Derrame pleural por IC.", "b": "Lesão do ducto torácico ou seus ramos durante a dissecção mediastinal.", "c": "Pericardite aguda.", "d": "Abscesso mediastinal precoce.", "e": "Fístula gástrica para o tórax."}, "answer": "b", "rationale": "O quilotórax/quilomediastino no pós-operatório cardíaco ocorre por trauma inadvertido do ducto torácico. O alto débito e o aspecto leitoso (após início de gordura na dieta) são clássicos.", "option_rationales": {"a": "Incorreta. Derrame pleural de IC é citrino, não leitoso.", "b": "Correta. Complicação anatômica traumática.", "c": "Incorreta.", "d": "Incorreta. Seria purulento e o paciente estaria instável.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Quilotórax", "Ducto Torácico"]}', 118, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 50 anos, obeso, tabagista, submetido a gastrectomia. No 5º DPO desenvolve deiscência de ferida operatória apenas da pele, com tecidos profundos íntegros. Qual a melhor conduta para a ferida infectada superficialmente?", "options": {"a": "Sutura imediata da pele novamente.", "b": "Tratamento por segunda intenção com curativos diários após limpeza e debridamento se necessário.", "c": "Colocar tela de polipropileno.", "d": "Uso de apenas pomada cicatrizante sem curativo.", "e": "Apenas observação sem manipulação."}, "answer": "b", "rationale": "Feridas infectadas não devem ser suturadas novamente (fechamento primário) pelo risco de abscesso. O tratamento ideal é a granulação espontânea por segunda intenção após controle da infecção local.", "option_rationales": {"a": "Incorreta. Vai infectar novamente e deiscer.", "b": "Correta. Manejo padrão para ISC incisional profunda ou superficial aberta.", "c": "Incorreta. Tela em ferida infectada é contraindicada.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Cicatrização", "ISC"]}', 119, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes submetidos a cirurgias prolongadas (> 4 horas), qual a principal medida de proteção ocular para evitar abrasão de córnea transperoperatória?", "options": {"a": "Uso de lentes de contato rígidas.", "b": "Manter os olhos fechados com fita adesiva hipoalérgica e/ou uso de lubrificantes oculares.", "c": "Instilar colírio de atropina.", "d": "Não há necessidade de proteção.", "e": "Uso de óculos de natação."}, "answer": "b", "rationale": "A perda do reflexo de piscamento e a redução da produção de lágrima sob anestesia geral podem levar ao ressecamento e abrasão da córnea pelo simples contato com campos cirúrgicos ou desidratação.", "option_rationales": {"a": "Incorreta. Pioraria o risco de lesão.", "b": "Correta. Protocolo de segurança anestésica básico.", "c": "Incorreta.", "d": "Incorreta. Abrasão de córnea é uma complicação relatada comum e evitável.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Segurança", "Lesão Ocular"]}', 120, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a transplante renal apresenta oligúria no pós-operatório imediato. O Doppler mostra fluxo adequado nas anastomoses arterial e venosa. O cirurgião decide realizar um teste de provocação com furosemida. Se o paciente não responder, qual a principal suspeita teórica excluída a obstrução?", "options": {"a": "NTA do enxerto (isquemia fria prolongada).", "b": "Rejeição hiperaguda.", "c": "Hematoma perinefrético.", "d": "Litíase ureteral iatrogênica.", "e": "Fístula urinária."}, "answer": "a", "rationale": "A NTA é comum em rins de doadores falecidos com longos tempos de isquemia. O rim transplantado pode demorar dias ou semanas para começar a funcionar (Delayed Graft Function).", "option_rationales": {"a": "Correta. Principal causa de disfunção inicial com Doppler normal.", "b": "Incorreta. Causaria trombose e ausência de fluxo no Doppler.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Urinoma daria dor e coleção, mas não necessariamente oligúria se o Doppler fosse normal e a produção existisse no espaço."}, "difficulty": "moderada", "tags": ["Urologia", "Pós-operatório", "Transplante Renal", "NTA"]}', 121, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A utilização de curativo com pressão negativa (Terapia a Vácuo) no pós-operatório de feridas complexas infectadas tem como principal objetivo:", "options": {"a": "Apenas esconder o odor.", "b": "Acelerar a formação de tecido de granulação, reduzir edema local e remover secreções e citocinas inflamatórias.", "c": "Substituir a necessidade de antibióticos sistêmicos.", "d": "Permitir que o paciente tome banho de mar precocemente.", "e": "Aumentar a tensão de oxigênio puramente."}, "answer": "b", "rationale": "A terapia a vácuo melhora a microcirculação e retira o excesso de líquido intersticial que impede a cicatrização, sendo superior ao curativo convencional em feridas de difícil fechamento.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo de ação da terapia de pressão negativa.", "c": "Incorreta. É adjuvante.", "d": "Incorreta.", "e": "Incorreta. Embora ajude na perfusão, o efeito mecânico e de drenagem é o principal."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Curativo", "Terapia a Vácuo"]}', 122, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma esternotomia, o paciente queixa-se de engasgos para sólidos e rouquidão moderada. Ele apresenta fraqueza no ombro ipsilateral com dificuldade para elevar o braço. Qual nervo craniano pode ter sido lesionado inadvertidamente?", "options": {"a": "Nervo Glossofaríngeo (IX).", "b": "Nervo Vago (X).", "c": "Nervo Acessório (XI).", "d": "Nervo Hipoglosso (XII).", "e": "Nervo Frênico."}, "answer": "c", "rationale": "O nervo acessório (XI) inerva o músculo trapézio e o esternocleidomastóideo. Sua lesão em manipulações cervicais ou proximais pode levar à fraqueza na elevação do ombro.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta. Rouquidão é do vago, mas a elevação do ombro aponta especificamente para o XI.", "c": "Correta. Quadro clínico de neuropatia do espinal acessório.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Neurologia", "Pós-operatório", "Lesão Nervosa", "Eletiva"]}', 123, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A tríade clássica para o diagnóstico de deiscência de ferida operatória laparotômica profunda (aponeurose) é composta por:", "options": {"a": "Febre, dor e pus.", "b": "Saída de secreção serossanguinolenta intensa, abaulamento local e sensação de ''rasgadura'' ou esforço súbito precedendo a drenagem.", "c": "Vômitos, icterícia e diarreia.", "d": "Equimose, prurido e edema.", "e": "Queda de pelos, pele seca e hipotermia."}, "answer": "b", "rationale": "A saída maciça de líquido rosado (cor de água de carne) é o sinal cardinal da deiscência aponeurótica. Geralmente ocorre após tosse, espirro ou esforço evacuatório.", "option_rationales": {"a": "Incorreta. Sugere infecção superficial, não deiscência necessariamente.", "b": "Correta. Semiologia clássica da evisceração iminente.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Parede Abdominal"]}', 124, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de pacientes submetidos a esplenectomia laparoscópica eletiva (por PTI, por exemplo), qual complicação vascular específica deve ser rastreada se houver dor abdominal súbita no 7º ao 10º DPO e aumento de plaquetas (> 1.000.000/mm³)?", "options": {"a": "Trombose de veia esplênica e/ou veia porta.", "b": "IAM agudo.", "c": "Fístula aorto-ilíaca.", "d": "Trombose de artéria renal.", "e": "Isquemia distal de membros."}, "answer": "a", "rationale": "A esplenectomia induz trombocitose reacional. Em conjunto com a estagnação do fluxo no coto da veia esplênica, há um risco aumentado de trombose de veia esplênica que pode progredir para a porta.", "option_rationales": {"a": "Correta. Complicação específica pós-esplenectomia.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Hematologia", "Pós-operatório", "Esplenectomia", "Trombose Porta"]}', 125, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia no 12º andar do hospital desenvolve no 3º DPO hipotensão, taquicardia e distensao de jugulares. O cirurgião diagnostica choque obstrutivo. Qual das opções abaixo pode causar este padrão hemodinâmico no pós-operatório?", "options": {"a": "Choque Séptico por pneumonia.", "b": "Choque Hipovolêmico por hemorragia.", "c": "Tromboembolismo Pulmonar maciço.", "d": "IAM com choque cardiogênico.", "e": "Sindrome do Intestino Curto."}, "answer": "c", "rationale": "O choque obstrutivo (TEP maciço, tamponamento cardíaco ou pneumotórax hipertensivo) caracteriza-se por turgência jugular (aumento da PVC) associada a hipotensão e baixo débito cardíaco por impedimento mecânico.", "option_rationales": {"a": "Incorreta. Distensao jugular não é comum no choque distributivo puro.", "b": "Incorreta. Jugulares estariam colabadas.", "c": "Correta. Causa frequente de choque obstrutivo pós-operatório.", "d": "Incorreta. Embora tenha turgência, o principal mecanismo é falha de bomba, mas o TEP é um diferencial clássico em pacientes cirúrgicos.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pós-operatório", "Choque Obstrutivo", "TEP"]}', 126, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 40 anos, diagnosticado com fístula pancreática após cirurgia biliar complexa, apresenta débito de 1.200 ml/dia pelo dreno. Qual a complicação eletrolítica mais comum diante desse alto débito de bicarbonato e líquidos?", "options": {"a": "Alcalose metabólica.", "b": "Hipernatremia severa.", "c": "Acidose metabólica hiperclorêmica.", "d": "Hipercalemia intensa.", "e": "Hipocalcemia aguda."}, "answer": "c", "rationale": "O suco pancreático é extremamente rico em bicarbonato. Sua perda maciça resulta em acidose pancreática (acidose metabólica com anion gap normal e hipercloremia).", "option_rationales": {"a": "Incorreta. Perda de suco gástrico (H+) daria alcalose.", "b": "Incorreta.", "c": "Correta. Fisiopatologia da perda de fluidos alcalinos distais.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula Pancreática", "Eletrólitos"]}', 127, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 4º DPO de uma cirurgia abdominal, o paciente apresenta febre de 38,5°C. Qual o foco infeccioso que deve ser investigado PRIORITARIAMENTE neste período, considerando ser a causa mais comum após o 3º dia?", "options": {"a": "Atelectasia pulmonar.", "b": "Infecção do sítio cirúrgico e Infecção do trato urinário (ITU).", "c": "Reação a anestésicos inalatórios.", "d": "Endocardite bacteriana aguda.", "e": "Malária hospitalar."}, "answer": "b", "rationale": "Enquanto a atelectasia é a causa comum nos primeiros 2 dias, a partir do 3º DPO as causas infecciosas bacterianas (Wound - ferida; Water - ITU) tornam-se predominantes.", "option_rationales": {"a": "Incorreta. Mais comum nas primeiras 48h.", "b": "Correta. Epidemiologia clássica da febre pós-operatória por dias.", "c": "Incorreta. Ocorre no transoperatório.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Febre", "Epidemiologia"]}', 128, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de icterícia (hiperbilirrubinemia à custa de bilirrubina indireta) em um paciente após cirurgia cardíaca prolongada com CEC e múltiplas transfusões de sangue estocado (pobre em glicose e com hemácias mais frágeis) é:", "options": {"a": "Coledocolitíase residual.", "b": "Hepatite viral C aguda.", "c": "Hemólise perioperatória e reabsorção de hematomas associada a disfunção hepática transitória por hipoperfusão.", "d": "Pancreatite biliar.", "e": "Síndrome de Gilbert manifestada pelo estresse."}, "answer": "c", "rationale": "A sobrecarga de hemoglobina livre (por hemólise na CEC ou transfusão) sobre um fígado ''atordoado'' pelo choque ou hipoperfusão da cirurgia leva a icterícia precoce benigna na maioria das vezes.", "option_rationales": {"a": "Incorreta. Icterícia obstrutiva seria à custa de bilirrubina direta.", "b": "Incorreta.", "c": "Correta. Causa comum de hiperbilirrubinemia pós-operatória multifatorial.", "d": "Incorreta.", "e": "Incorreta. Embora possível, a sobrecarga hemolítica cirúrgica é a causa primária principal."}, "difficulty": "moderada", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Icterícia", "Hemólise"]}', 129, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal por câncer queixa-se no 5º DPO de fraqueza nos membros inferiores. O exame físico revela reflexos diminuídos e força muscular reduzida bilateralmente. O ECG mostra ondas T achatadas e presença de ondas U. Qual o tratamento prioritário?", "options": {"a": "Diálise imediata para retirar potássio.", "b": "Reposição de potássio (K+) endovenosa ou oral, conforme a urgência.", "c": "Uso de insulina para baixar o potássio.", "d": "Solicitar RNM de coluna.", "e": "Tratar como Guillain-Barré."}, "answer": "b", "rationale": "O quadro de fraqueza muscular e alterações no ECG (onda U) é clássico de hipocalemia severa. O cirurgião deve repor potássio atentamente.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico e conduta baseados no ECG e clínica.", "c": "Incorreta. Insulina piora a hipocalemia.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Clínica Médica", "Pós-operatório", "Eletrólitos", "Hipocalemia"]}', 130, 'draft')
